@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ---------------------------------------------------------------------------
   View transitions
   ------------------------------------------------------------------------- */

:root {
  --vt-duration-exit: 150ms;
  --vt-duration-enter: 210ms;
  --vt-slide-offset: 60px;
}

/* Directional page navigation: forward pushes content left, back pushes right */
::view-transition-old(.nav-forward) {
  --vt-slide-offset: -60px;
  animation:
    var(--vt-duration-exit) ease-in both vt-fade reverse,
    400ms ease-in-out both vt-slide-x reverse;
}
::view-transition-new(.nav-forward) {
  --vt-slide-offset: 60px;
  animation:
    var(--vt-duration-enter) ease-out var(--vt-duration-exit) both vt-fade,
    400ms ease-in-out both vt-slide-x;
}

::view-transition-old(.nav-back) {
  --vt-slide-offset: 60px;
  animation:
    var(--vt-duration-exit) ease-in both vt-fade reverse,
    400ms ease-in-out both vt-slide-x reverse;
}
::view-transition-new(.nav-back) {
  --vt-slide-offset: -60px;
  animation:
    var(--vt-duration-enter) ease-out var(--vt-duration-exit) both vt-fade,
    400ms ease-in-out both vt-slide-x;
}

/* Suspense reveal: the skeleton yields to the real content */
::view-transition-old(.slide-down) {
  animation:
    var(--vt-duration-exit) ease-out both vt-fade reverse,
    var(--vt-duration-exit) ease-out both vt-slide-y reverse;
}
::view-transition-new(.slide-up) {
  animation:
    var(--vt-duration-enter) ease-in var(--vt-duration-exit) both vt-fade,
    400ms ease-in both vt-slide-y;
}

@keyframes vt-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes vt-slide-x {
  from {
    translate: var(--vt-slide-offset);
  }
  to {
    translate: 0;
  }
}

@keyframes vt-slide-y {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}

/* Respect the user's motion preference: disable every animation */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-old(*),
  ::view-transition-new(*),
  ::view-transition-group(*) {
    animation-duration: 0s !important;
    animation-delay: 0s !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none !important;
  }
}

